/** Core 0.2.2 contract references; generated by the Rust fixture in fixtures/existence_contract_vectors.rs. */
import { assertEquals } from "@std/assert";
import { contractIri } from "../src/contract.ts";
import { actionSpec, type Json, VectorDoor } from "./vector_door.ts";

const vectors: {
  name: string;
  id: string;
  action: Json;
  contract: string;
}[] = JSON.parse(
  await Deno.readTextFile(
    new URL("./existence_contract_vectors.json", import.meta.url),
  ),
);

for (const vector of vectors) {
  Deno.test(`core 0.2.2 existence contract: ${vector.name}`, () => {
    assertEquals(
      contractIri(vector.id, actionSpec(vector.action)),
      vector.contract,
    );
    const door = new VectorDoor({
      id: vector.id,
      title: "",
      summary: "",
      verbs: ["Source", "Meta"],
      inputs: [],
      outputs: [],
      actions: [vector.action],
    });
    assertEquals(door.descriptionJson()["actions"], [vector.action]);
    assertEquals(
      door.descriptionTurtle().includes(`<${vector.contract}> a ik:Action`),
      true,
    );
  });
}

Deno.test("flat sensitivity reaches synthesized contracts; explicit actions replace it", () => {
  const description: Json = {
    id: "state",
    title: "",
    summary: "",
    verbs: ["Source", "Sink", "Meta"],
    inputs: [],
    outputs: [],
    requires: ["urn:cap:x"],
    existence_sensitive: true,
    actions: [{ verb: "Sink", existence_sensitive: false }],
  };
  const door = new VectorDoor(description);
  const json = door.descriptionJson();
  assertEquals(json["existence_sensitive"], true);
  assertEquals(json["actions"], [{ verb: "Sink" }]);
  const turtle = door.descriptionTurtle();
  assertEquals(turtle.includes(`<${vectors[0].contract}> a ik:Action`), true);
  assertEquals(turtle.match(/ik:existenceSensitive true/g)?.length, 2);
  for (
    const vector of vectors.filter((v) => !v.action["existence_sensitive"])
  ) {
    const spec = actionSpec(vector.action);
    assertEquals(
      contractIri(vector.id, { ...spec, existenceSensitive: false }),
      vector.contract,
    );
  }
  const open = new VectorDoor({ ...description, existence_sensitive: false });
  assertEquals("existence_sensitive" in open.descriptionJson(), false);
  assertEquals(
    open.descriptionTurtle().includes("ik:existenceSensitive"),
    false,
  );
});
